import java.util.*;
import java.io.*;

public class Main {
    static final long k = 1000000007L;
    static List<List<Integer>> v = new ArrayList<>();
    static long[] b;
    static long[] p;
    static long[] a;
    static long[] n;
    static Map<Long, Long>[] dp;
    static int nSize;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        nSize = Integer.parseInt(br.readLine());
        int maxMask = 1 << nSize;
        b = new long[maxMask];
        p = new long[nSize];
        a = new long[nSize];

        // Initialize v with empty lists
        for (int i = 0; i <= nSize; i++) {
            v.add(new ArrayList<>());
        }

        // Populate v and b
        for (int i = 0; i < maxMask; i++) {
            int j = Integer.bitCount(i);
            b[i] = v.get(j).size();
            v.get(j).add(i);
        }

        // Initialize dp array
        dp = new Map[nSize + 1];
        for (int i = 0; i <= nSize; i++) {
            dp[i] = new HashMap<>();
        }
        dp[0].put(1L, 1L);

        for (int i = 0; i < nSize; i++) {
            String[] pValues = br.readLine().split(" ");
            for (int j = 0; j < nSize; j++) {
                p[j] = Long.parseLong(pValues[j]) * 570000004L % k;
            }

            Map<Long, Long> currentDP = dp[i];
            Map<Long, Long> nextDP = dp[i + 1];

            for (Map.Entry<Long, Long> entry : currentDP.entrySet()) {
                long maskCount = entry.getKey();
                long ways = entry.getValue();

                for (long msk : v.get(i)) {
                    long bitCount = b[(int) msk];
                    if (((maskCount >> bitCount) & 1) == 1) {
                        for (int j = 0; j < nSize; j++) {
                            if (((msk >> j) & 1) == 0) {
                                long newMask = 0;
                                for (long m : v.get(i)) {
                                    if (((maskCount >> b[(int) m]) & 1) == 1) {
                                        newMask |= (1L << b[(int) (m | (1 << j))]);
                                    }
                                }
                                long X = 1;
                                long M = newMask;
                                for (int j2 = 0; j2 < nSize; j2++) {
                                    if (((msk >> j2) & 1) == 1) {
                                        M |= a[j2];
                                        X = (X * p[j2]) % k;
                                    } else {
                                        X = (X * (k - p[j2] + 1) % k) % k;
                                    }
                                }
                                nextDP.put(M, (nextDP.getOrDefault(M, 0L) + ways * X) % k);
                            }
                        }
                    }
                }
            }
        }

        System.out.println(dp[nSize].getOrDefault(1L, 0L));
    }
}
